#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 long long putMarbles(vector<int>& weights,int k){
  vector<long long> cuts;for(int i=1;i<(int)weights.size();++i)cuts.push_back((long long)weights[i-1]+weights[i]);
  sort(cuts.begin(),cuts.end());long long ans=0;
  for(int i=0;i<k-1;++i)ans+=cuts[cuts.size()-1-i]-cuts[i];return ans;
 }
};
